import { useEffect, useMemo, useState } from 'react';
import { useRoute, useLocation } from 'wouter';
import AdminLayout from '@/components/admin/AdminLayout';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { Save, ArrowLeft } from 'lucide-react';

interface ProductForm {
  name: string;
  displayTitle: string;
  description: string;
  category: string;
  price: number;
  stockQuantity: number;
  imageUrl: string;
  texturePhotoUrl: string;
  sizeOptionsInput: string;
  isWholesaleOnly: boolean;
  allowBulkPickup: boolean;
}

const categories = [
  'Compost',
  'Amendment',
  'Mulch',
  'Potting Soil',
];

const DEFAULT_SIZES = '9lb Bag,25lb Bag,Bulk (50lb)';

const AdminProductEdit = () => {
  const [matchEdit, paramsEdit] = useRoute('/admin/products/:id/edit');
  const [matchNew] = useRoute('/admin/products/new');
  const [, navigate] = useLocation();
  const productId = paramsEdit?.id;
  const isNew = matchNew || productId === 'new';

  const { toast } = useToast();
  const [loading, setLoading] = useState(!isNew);
  const [saving, setSaving] = useState(false);

  const [form, setForm] = useState<ProductForm>({
    name: '',
    displayTitle: '',
    description: '',
    category: categories[0],
    price: 0,
    stockQuantity: 0,
    imageUrl: '',
    texturePhotoUrl: '',
    sizeOptionsInput: DEFAULT_SIZES,
    isWholesaleOnly: false,
    allowBulkPickup: true,
  });

  useEffect(() => {
    if (!isNew) {
      fetchProduct();
    }
  }, [productId, isNew]);

  const fetchProduct = async () => {
    try {
      const response = await fetch(`/api/admin/products/${productId}`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('adminToken')}`,
        },
      });

      if (!response.ok) throw new Error('Failed to fetch product');

      const data = await response.json();

      setForm({
        name: data.name || '',
        displayTitle: data.displayTitle || data.name || '',
        description: data.description || '',
        category: data.category || categories[0],
        price: data.price || 0,
        stockQuantity: data.stockQuantity || 0,
        imageUrl: data.imageUrl || '',
        texturePhotoUrl: data.texturePhotoUrl || '',
        sizeOptionsInput: Array.isArray(data.availableSizes) && data.availableSizes.length > 0
          ? data.availableSizes.join(', ')
          : DEFAULT_SIZES,
        isWholesaleOnly: data.isWholesaleOnly ?? false,
        allowBulkPickup: data.allowBulkPickup ?? true,
      });
    } catch (error) {
      console.error('Error loading product:', error);
      toast({
        title: 'Error',
        description: 'Failed to load product details.',
        variant: 'destructive',
      });
      navigate('/admin/products');
    } finally {
      setLoading(false);
    }
  };

  const availableSizes = useMemo(
    () =>
      form.sizeOptionsInput
        .split(',')
        .map((size) => size.trim())
        .filter(Boolean),
    [form.sizeOptionsInput],
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    try {
      const payload = {
        name: form.name,
        productType: form.displayTitle || form.name,
        displayTitle: form.displayTitle || form.name,
        marketingTitle: form.displayTitle || form.name,
        description: form.description,
        category: form.category,
        price: form.price,
        stockQuantity: form.stockQuantity,
        imageUrl: form.imageUrl,
        texturePhotoUrl: form.texturePhotoUrl,
        isWholesaleOnly: form.isWholesaleOnly,
        allowBulkPickup: form.allowBulkPickup,
        availableSizes,
      };

      const url = isNew ? '/api/admin/products' : `/api/admin/products/${productId}`;
      const method = isNew ? 'POST' : 'PUT';

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('adminToken')}`,
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) throw new Error('Failed to save product');

      toast({
        title: 'Success',
        description: `Product ${isNew ? 'created' : 'updated'} successfully.`,
      });
      navigate('/admin/products');
    } catch (error) {
      console.error('Error saving product:', error);
      toast({
        title: 'Error',
        description: 'Failed to save product.',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="p-6">Loading product...</div>;
  }

  return (
    <AdminLayout>
      <form onSubmit={handleSubmit} className="space-y-6 max-w-4xl mx-auto">
        <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <div className="flex items-center gap-3">
            <Button variant="ghost" type="button" onClick={() => navigate('/admin/products')}>
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Products
            </Button>
            <h1 className="text-2xl font-bold leading-tight">
              {isNew ? 'Create Product' : `Edit ${form.displayTitle || form.name}`}
            </h1>
          </div>
          <Button type="submit" disabled={saving} className="md:self-end">
            <Save className="h-4 w-4 mr-2" />
            {saving ? 'Saving...' : 'Save Product'}
          </Button>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Product Basics</CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <Label htmlFor="name">Product Name</Label>
                <Input
                  id="name"
                  value={form.name}
                  onChange={(e) => setForm((prev) => ({ ...prev, name: e.target.value }))}
                  placeholder="Dan's Gold Dairy Compost"
                  required
                />
              </div>
              <div>
                <Label htmlFor="displayTitle">Display Title</Label>
                <Input
                  id="displayTitle"
                  value={form.displayTitle}
                  onChange={(e) => setForm((prev) => ({ ...prev, displayTitle: e.target.value }))}
                  placeholder="Customer-facing title (optional)"
                />
              </div>
              <div>
                <Label htmlFor="category">Category</Label>
                <Select
                  value={form.category}
                  onValueChange={(value) => setForm((prev) => ({ ...prev, category: value }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select a category" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((category) => (
                      <SelectItem key={category} value={category}>
                        {category}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="price">Price</Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  min="0"
                  value={form.price}
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      price: parseFloat(e.target.value) || 0,
                    }))
                  }
                  placeholder="24.99"
                />
              </div>
              <div>
                <Label htmlFor="stockQuantity">Starting Inventory</Label>
                <Input
                  id="stockQuantity"
                  type="number"
                  min="0"
                  value={form.stockQuantity}
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      stockQuantity: parseInt(e.target.value, 10) || 0,
                    }))
                  }
                  placeholder="150"
                />
              </div>
              <div>
                <Label htmlFor="sizeOptionsInput">Available Sizes</Label>
                <Input
                  id="sizeOptionsInput"
                  value={form.sizeOptionsInput}
                  onChange={(e) =>
                    setForm((prev) => ({ ...prev, sizeOptionsInput: e.target.value }))
                  }
                  placeholder="9lb Bag, 25lb Bag, Bulk (50lb)"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Separate sizes with commas. These show in Pay &amp; Pickup.
                </p>
              </div>
            </div>

            <div>
              <Label htmlFor="description">Quick Description</Label>
              <Textarea
                id="description"
                value={form.description}
                onChange={(e) => setForm((prev) => ({ ...prev, description: e.target.value }))}
                rows={4}
                placeholder="What should landscapers know about this product?"
              />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Photos</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label htmlFor="texturePhotoUrl">Texture Photo URL</Label>
              <Input
                id="texturePhotoUrl"
                value={form.texturePhotoUrl}
                onChange={(e) =>
                  setForm((prev) => ({ ...prev, texturePhotoUrl: e.target.value }))
                }
                placeholder="https://...texture.jpg"
              />
              <p className="text-xs text-muted-foreground mt-1">
                This is the first photo customers see (close-up of the soil).
              </p>
            </div>
            <div>
              <Label htmlFor="imageUrl">Bag / Product Photo URL</Label>
              <Input
                id="imageUrl"
                value={form.imageUrl}
                onChange={(e) => setForm((prev) => ({ ...prev, imageUrl: e.target.value }))}
                placeholder="https://...bag.jpg"
              />
              <p className="text-xs text-muted-foreground mt-1">
                Optional hero shot of the bag or product packaging.
              </p>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Availability</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex items-center justify-between rounded-lg border p-4">
              <div>
                <span className="font-medium block">Wholesale Only</span>
                <p className="text-sm text-muted-foreground">
                  Hide from retail shoppers.
                </p>
              </div>
              <Switch
                checked={form.isWholesaleOnly}
                onCheckedChange={(checked) =>
                  setForm((prev) => ({ ...prev, isWholesaleOnly: checked }))
                }
              />
            </div>
            <div className="flex items-center justify-between rounded-lg border p-4">
              <div>
                <span className="font-medium block">Allow Pay &amp; Pickup</span>
                <p className="text-sm text-muted-foreground">
                  Show in the drive-through checkout.
                </p>
              </div>
              <Switch
                checked={form.allowBulkPickup}
                onCheckedChange={(checked) =>
                  setForm((prev) => ({ ...prev, allowBulkPickup: checked }))
                }
              />
            </div>
          </CardContent>
        </Card>
      </form>
    </AdminLayout>
  );
};

export default AdminProductEdit;
