import { Switch, Route, useLocation } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { HelmetProvider } from "react-helmet-async";
import NotFound from "@/pages/not-found";
import { ThemeProvider } from "@/components/ui/theme-provider";
import Header from "@/components/layout/Header";
import Footer from "@/components/layout/Footer";
import FloatingCTA from "@/components/layout/FloatingCTA";
import Home from "@/pages/Home";
import Products from "@/pages/Products";
import ProductDetail from "@/pages/ProductDetail";
import MulchDetail from "@/pages/MulchDetail";
import About from "@/pages/About";
import Contact from "@/pages/Contact";
import FAQ from "@/pages/FAQ";
import Order from "@/pages/Order";
import SpecialRequest from "@/pages/SpecialRequest";
import Landscapers from "@/pages/Landscapers";
import Wholesale from "@/pages/Wholesale";
import Terms from "@/pages/Terms";
import Privacy from "@/pages/Privacy";
import StoreLocator from "@/pages/StoreLocator";
import StoreLocatorMapbox from "@/pages/StoreLocatorMapbox";
import StoreLocatorWithRouting from "@/pages/StoreLocatorWithRouting";
import StoreLocatorEnhanced from "@/pages/StoreLocatorEnhanced";
import PayAndPickup from "@/pages/PayAndPickup";
import Checkout from "@/pages/Checkout";
import OrderConfirmation from "@/pages/OrderConfirmation";
import { useEffect } from "react";
import { Analytics } from "@vercel/analytics/react";
import TriviaGame from "@/pages/TriviaGame";

// Customer Auth imports
import SignIn from "@/pages/SignIn";
import SignUp from "@/pages/SignUp";
import SignUpSuccess from "@/pages/SignUpSuccess";
import ForgotPassword from "@/pages/ForgotPassword";
import ResetPassword from "@/pages/ResetPassword";
import VerifyEmail from "@/pages/VerifyEmail";
import { AuthProvider } from "@/contexts/AuthContext";

// Admin imports
import AdminLogin from "@/pages/admin/Login";
import AdminDashboard from "@/pages/admin/Dashboard";
import AdminProducts from "@/pages/admin/Products";
import AdminProductEdit from "@/pages/admin/ProductEdit";
import AdminInventory from "@/pages/admin/Inventory";
import AdminCustomers from "@/pages/admin/Customers";
import AdminAnalytics from "@/pages/admin/Analytics";
import AdminDriveThrough from "@/pages/admin/DriveThrough";
import ProtectedAdminRoute from "@/components/admin/ProtectedAdminRoute";
import { AdminAuthProvider } from "@/hooks/useAdminAuth";

// ScrollToTop component to handle auto-scrolling
const ScrollToTop = () => {
  const [location] = useLocation();

  useEffect(() => {
    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  }, [location]);

  return null;
};

function Router() {
  return (
    <Switch>
      <Route path="/" component={Home} />
      <Route path="/products" component={Products} />
      <Route path="/products/mulch/:id" component={MulchDetail} />
      <Route path="/products/:slug" component={ProductDetail} />
      <Route path="/about" component={About} />
      <Route path="/contact" component={Contact} />
      <Route path="/faq" component={FAQ} />
      <Route path="/order" component={Order} />
      <Route path="/special-request" component={SpecialRequest} />
      <Route path="/landscapers" component={Landscapers} />
      <Route path="/wholesale" component={Wholesale} />
      <Route path="/terms" component={Terms} />
      <Route path="/privacy" component={Privacy} />
      <Route path="/store-locator" component={StoreLocatorEnhanced} />
      <Route path="/pay-and-pickup" component={PayAndPickup} />
      <Route path="/drive-through" component={PayAndPickup} />
      <Route path="/trivia" component={TriviaGame} />
      <Route path="/checkout" component={Checkout} />
      <Route path="/order-confirmation" component={OrderConfirmation} />

      {/* Customer Auth Routes */}
      <Route path="/signin" component={SignIn} />
      <Route path="/signup" component={SignUp} />
      <Route path="/signup-success" component={SignUpSuccess} />
      <Route path="/forgot-password" component={ForgotPassword} />
      <Route path="/reset-password/:token" component={ResetPassword} />
      <Route path="/verify-email/:token" component={VerifyEmail} />

      {/* Admin Routes */}
      <Route path="/admin/login" component={AdminLogin} />
      <Route
        path="/admin"
        component={() => (
          <ProtectedAdminRoute>
            <AdminDashboard />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/dashboard"
        component={() => (
          <ProtectedAdminRoute>
            <AdminDashboard />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/products"
        component={() => (
          <ProtectedAdminRoute>
            <AdminProducts />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/products/new"
        component={() => (
          <ProtectedAdminRoute>
            <AdminProductEdit />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/products/:id/edit"
        component={() => (
          <ProtectedAdminRoute>
            <AdminProductEdit />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/inventory"
        component={() => (
          <ProtectedAdminRoute>
            <AdminInventory />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/customers"
        component={() => (
          <ProtectedAdminRoute>
            <AdminCustomers />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/analytics"
        component={() => (
          <ProtectedAdminRoute>
            <AdminAnalytics />
          </ProtectedAdminRoute>
        )}
      />
      <Route
        path="/admin/drive-through"
        component={() => (
          <ProtectedAdminRoute>
            <AdminDriveThrough />
          </ProtectedAdminRoute>
        )}
      />

      <Route component={NotFound} />
    </Switch>
  );
}

function App() {
  const [location] = useLocation();
  const isPayAndPickup = location === "/pay-and-pickup" || location === "/drive-through";
  const isTriviaGame = location === "/trivia";
  const isCheckoutFlow = location === "/checkout" || location === "/order-confirmation" || location === "/quick-order";
  const isAdminRoute = location.startsWith("/admin");

  return (
    <QueryClientProvider client={queryClient}>
      <HelmetProvider>
        <ThemeProvider defaultTheme="light" storageKey="vite-ui-theme">
          <AuthProvider>
            <AdminAuthProvider>
              <TooltipProvider>
                <div className="min-h-screen flex flex-col">
                  {!isPayAndPickup && !isTriviaGame && !isCheckoutFlow && !isAdminRoute && <Header />}
                  <main className={`flex-grow ${!isPayAndPickup && !isTriviaGame && !isCheckoutFlow && !isAdminRoute ? "pt-20" : ""}`}>
                    <Router />
                  </main>
                  {!isPayAndPickup && !isTriviaGame && !isCheckoutFlow && !isAdminRoute && <Footer />}
                  <Toaster />
                  <ScrollToTop />
                  <Analytics />
                  {!isPayAndPickup && !isTriviaGame && !isCheckoutFlow && !isAdminRoute && <FloatingCTA />}
                </div>
              </TooltipProvider>
            </AdminAuthProvider>
          </AuthProvider>
        </ThemeProvider>
      </HelmetProvider>
    </QueryClientProvider>
  );
}

export default App;
