import { forwardRef, type ImgHTMLAttributes } from "react";
import { getOptimizedImageSrc } from "@/utils/getOptimizedImageSrc";

export interface OptimizedImageProps extends ImgHTMLAttributes<HTMLImageElement> {
  src: string;
}

export const OptimizedImage = forwardRef<HTMLImageElement, OptimizedImageProps>(
  ({ src, loading, decoding, ...props }, ref) => {
    const resolvedSrc = getOptimizedImageSrc(src);

    return (
      <img
        ref={ref}
        src={resolvedSrc}
        loading={loading ?? "lazy"}
        decoding={decoding ?? "async"}
        {...props}
      />
    );
  }
);

OptimizedImage.displayName = "OptimizedImage";
